package com.honorablemobile

import android.app.AlertDialog
import android.net.Uri
import app.honorable.editor.EditorAccessMode
import org.junit.Assert.*
import org.junit.Test

/** Real visible-approval/project mutation gates, with metadata-only dialog membership. */
class VideoPacedCaptionsTest {
 private val unsafe=Class.forName("sun.misc.Unsafe").getDeclaredField("theUnsafe").apply{isAccessible=true}.get(null)as sun.misc.Unsafe
 private fun set(a:Any,n:String,v:Any?)=a.javaClass.getDeclaredField(n).apply{isAccessible=true}.set(a,v)
 private fun get(a:Any,n:String)=a.javaClass.getDeclaredField(n).apply{isAccessible=true}.get(a)
 private fun call(a:Any,n:String,vararg args:Any?)=a.javaClass.declaredMethods.single{it.name==n&&it.parameterCount==args.size}.apply{isAccessible=true}.invoke(a,*args)
 private fun activity()=(unsafe.allocateInstance(HonorableVideoEditorActivity::class.java)as HonorableVideoEditorActivity).also{val p=VideoEditProject(5000);p.restore(listOf(VideoSegment(0,5000,captions=listOf(VideoCaption(0,500,"A"),VideoCaption(1000,1500,"B")),captionSourceUri="content://synthetic/subtitles")),soundtrack=VideoSoundtrack("content://synthetic/music",10000,loop=false));set(it,"project",p);set(it,"source",Uri.parse("content://synthetic/video"));set(it,"primaryDurationMs",5000L);set(it,"accessMode",EditorAccessMode.GUEST_BASIC);set(it,"workspaceActive",true);set(it,"importedSources",linkedMapOf<String,VideoSource>())}
 private fun showing(d:AlertDialog,value:Boolean){android.app.Dialog::class.java.getDeclaredField("mDecor").apply{isAccessible=true}.set(d,if(value)unsafe.allocateInstance(android.view.View::class.java)else null)}
 private fun dialog()=(unsafe.allocateInstance(AlertDialog::class.java)as AlertDialog).also{showing(it,true)}
 private fun capture(a:HonorableVideoEditorActivity)=call(a,"captureCaptionReview")as VideoCaptionReviewState
 private fun clips(start:Long=0,end:Long=8000,speed:Float=1f)=listOf(VideoSegment(start,end,speed=speed))
 private fun plan(text:String="one two three four five six seven eight",size:Int=2,c:List<VideoSegment> = clips())=VideoPacedCaptions.prepare(c,0,text,size)
 private fun rejects(action:()->Unit){try{action();fail("Expected refusal")}catch(_:IllegalArgumentException){}}
 @Test fun whitespaceAndPunctuationArePreservedWithoutSpeechClaims(){val p=plan("  Hello,\tworld!\n你好\u00a0мир  ");assertEquals(listOf("Hello, world!","你好 мир"),p.cues.map{it.text});assertEquals(0L,p.cues.first().startMs);assertEquals(8000L,p.cues.last().endMs)}
 @Test fun sourceTrimAndFinalShortGroupUseWordProportions(){val p=plan(size=3,c=clips(1000,5000));assertEquals(listOf(1000L,2500L,4000L),p.cues.map{it.startMs});assertEquals(listOf(2500L,4000L,5000L),p.cues.map{it.endMs});assertEquals("seven eight",p.cues.last().text)}
 @Test fun speedUsesSourceTimeAndExistingPlaybackMapping(){val p=plan(size=3,c=clips(1000,5000,2f));val resolved=VideoCaptions.resolve(listOf(p.base[0].copy(captions=p.cues)));assertEquals(listOf(0L,750000L,1500000L),resolved.map{it.startUs});assertEquals(2000000L,resolved.last().endUs)}
 @Test fun emptyControlAndMalformedUnicodeAreRejected(){for(text in listOf("","  \n\t","a\u0000b","a\u001bb","\uD800"))rejects{plan(text)}}
 @Test fun characterAndUtf8BoundsAreSeparate(){rejects{plan("x".repeat(8001))};rejects{plan("界".repeat(6000))};assertTrue(plan("word ".repeat(200),12,c=clips(0,200000)).cues.isNotEmpty())}
 @Test fun wordAndGroupingBoundsAreExplicit(){rejects{plan("a ".repeat(1001),12,c=clips(0,1000000))};for(n in listOf(0,13,-1))rejects{plan(size=n)}}
 @Test fun oversizedCaptionGroupIsRefusedWithoutTruncation(){rejects{plan("x".repeat(241))};rejects{plan("x".repeat(121)+" "+"y".repeat(121))};assertEquals(240,plan("x".repeat(240)).cues.single().text.length)}
 @Test fun minimumPlaybackHoldAccountsForSpeed(){rejects{plan("one two",1,c=clips(0,999,2f))};assertEquals(2,plan("one two",1,c=clips(0,1000,2f)).cues.size)}
 @Test fun perClipCueLimitIsEnforced(){assertEquals(200,plan("a ".repeat(200),1,c=clips(0,100000)).cues.size);rejects{plan("a ".repeat(201),1,c=clips(0,100000))}}
 @Test fun proposalCopiesInputsAndCannotBeModified(){val original=mutableListOf(VideoCaption(0,500,"Old"));val input=mutableListOf(VideoSegment(0,8000,captions=original));val p=plan(c=input);original.clear();input.clear();assertEquals("Old",p.base[0].captions.single().text);try{(p.cues as MutableList).clear();fail("Mutable cues")}catch(_:UnsupportedOperationException){};try{(p.base as MutableList).clear();fail("Mutable base")}catch(_:UnsupportedOperationException){}}
 @Test fun applyingPreservesOtherClipMusicOriginalDocumentAndOneUndo(){val p=VideoEditProject(8000);val source=VideoSegment(0,8000,captions=listOf(VideoCaption(0,500,"Old")),captionSourceUri="content://synthetic/srt");val other=VideoSegment(0,5000,title="Other");val music=VideoSoundtrack("content://synthetic/music",10000);p.restore(listOf(source,other),soundtrack=music);val plan=VideoPacedCaptions.prepare(p.segments,0,"a b c d",2,music);plan.apply(p){};assertSame(other,p.segments[1]);assertSame(music,p.soundtrack);assertEquals(source.captionSourceUri,p.segments[0].captionSourceUri);assertTrue(p.captionSourceUris().contains(source.captionSourceUri));assertTrue(p.undo());assertEquals(source,p.segments[0]);assertFalse(p.canUndo);assertTrue(p.redo());assertEquals(plan.cues,p.segments[0].captions)}
 @Test fun changedProjectOrMusicRejectsApply(){for(music in listOf(false,true)){val p=VideoEditProject(8000);val proposal=VideoPacedCaptions.prepare(p.segments,0,"a b c d",2,p.soundtrack);if(music)p.setSoundtrack(VideoSoundtrack("content://synthetic/music",10000))else p.setTitle(0,"Changed");val before=p.segments;try{proposal.apply(p){};fail("Stale applied")}catch(_:IllegalArgumentException){};assertSame(before,p.segments)}}
 @Test fun prepareChecksCurrentOwnerDuringAndAfterWork(){var count=0;try{VideoPacedCaptions.prepare(clips(),0,"a b c d",2){count++;check(count<3){"Cancelled"}};fail("Ignored guard")}catch(e:IllegalStateException){assertEquals("Cancelled",e.message)};assertEquals(3,count)}
 @Test fun applyChecksOwnerBeforeHistoryChanges(){val p=VideoEditProject(8000);val proposal=VideoPacedCaptions.prepare(p.segments,0,"a b",1);try{proposal.apply(p){error("Closed")};fail("Ignored guard")}catch(e:IllegalStateException){assertEquals("Closed",e.message)};assertFalse(p.canUndo);assertTrue(p.segments[0].captions.isEmpty())}
 @Test fun wholeProjectCueAndByteLimitsAreChecked(){val cues=(0 until 200).map{VideoCaption(it*1000L,it*1000L+500,"a")};val many=listOf(VideoSegment(0,300000))+List(5){VideoSegment(0,300000,captions=cues)};rejects{plan("new",1,many)};val bytes=cues.map{it.copy(text="x".repeat(64))};val full=listOf(VideoSegment(0,300000))+List(5){VideoSegment(0,300000,captions=bytes)};rejects{plan("new",1,full)}}
 @Test fun invalidSelectionAndNoOpCannotChangeHistory(){rejects{VideoPacedCaptions.prepare(clips(),1,"a",1)};val p=VideoEditProject(8000);p.restore(listOf(VideoSegment(0,8000,captions=listOf(VideoCaption(0,8000,"same")))));val proposal=VideoPacedCaptions.prepare(p.segments,0,"same",1);assertFalse(proposal.changed);rejects{proposal.apply(p){}};assertFalse(p.canUndo)}
 private fun commit(a:HonorableVideoEditorActivity,d:AlertDialog,r:VideoCaptionReviewState,p:VideoPacedCaptions)=call(a,"commitPacedCaptions",d,r,p)as Boolean
 @Test fun realVisibleReviewCommitsOneUndo(){val a=activity();val p=get(a,"project")as VideoEditProject;val old=p.segments;val r=capture(a);val d=dialog();set(a,"captionReviewDialogs",linkedSetOf(d));val proposal=VideoPacedCaptions.prepare(p.segments,0,"new words here",2,p.soundtrack);assertTrue(commit(a,d,r,proposal));assertEquals(proposal.cues,p.segments[0].captions);assertTrue(p.undo());assertEquals(old,p.segments);assertFalse(p.canUndo)}
 @Test fun cancelledOrDismissedReviewCannotCommit(){for(decor in listOf(false,true)){val a=activity();val p=get(a,"project")as VideoEditProject;val r=capture(a);val d=dialog();set(a,"captionReviewDialogs",if(decor)linkedSetOf(d)else linkedSetOf<AlertDialog>());if(decor)showing(d,false);val proposal=VideoPacedCaptions.prepare(p.segments,0,"new words",2,p.soundtrack);assertFalse(commit(a,d,r,proposal));assertFalse(p.canUndo)}}
 @Test fun staleSessionGenerationSourceAndRecoveryRejectCommit(){for(flag in listOf("pause","generation","source","mode","recovery","busy")){val a=activity();val p=get(a,"project")as VideoEditProject;val r=capture(a);val d=dialog();set(a,"captionReviewDialogs",linkedSetOf(d));val proposal=VideoPacedCaptions.prepare(p.segments,0,"new words",2,p.soundtrack);when(flag){"pause"->set(a,"workspaceActive",false);"generation"->set(a,"captionReviewGeneration",r.generation+1);"source"->set(a,"source",Uri.parse("content://synthetic/other"));"mode"->set(a,"accessMode",EditorAccessMode.ACCOUNT);"recovery"->set(a,"recoveryBytes",byteArrayOf(1));else->set(a,"saving",true)};assertFalse(flag,commit(a,d,r,proposal));assertFalse(p.canUndo)}}
 @Test fun cancellingThenUndoDoesNotReviveOldProposal(){val a=activity();val p=get(a,"project")as VideoEditProject;val r=capture(a);val d=dialog();val live=linkedSetOf(d);set(a,"captionReviewDialogs",live);val proposal=VideoPacedCaptions.prepare(p.segments,0,"new words",2,p.soundtrack);assertTrue(commit(a,d,r,proposal));live.clear();assertTrue(p.undo());assertEquals(true,call(a,"canApplyCaptionReview",r));assertFalse(commit(a,d,r,proposal));assertFalse(p.canUndo);assertTrue(p.canRedo)}
 @Test fun pacedCaptionsSurviveExistingDraftRecoveryWithSourceReferenceAndMusic(){val p=VideoEditProject(8000);val music=VideoSoundtrack("content://synthetic/music",10000);p.restore(listOf(VideoSegment(1000,7000,speed=2f,captionSourceUri="content://synthetic/srt")),soundtrack=music);val proposal=VideoPacedCaptions.prepare(p.segments,0,"one two three four",2,music);proposal.apply(p){};val draft=VideoDraft(8000,p.segments,0,1000,1000,7000,soundtrack=music);val restored=requireNotNull(VideoDraftCodec.decode(VideoDraftCodec.encode(draft),8000));assertEquals(draft,restored);assertEquals(proposal.cues,restored.segments[0].captions);assertEquals("content://synthetic/srt",restored.segments[0].captionSourceUri)}
 @Test fun generatedSrtMatchesTrimmedSpeedAdjustedPlaybackAfterApply(){val p=VideoEditProject(8000);p.restore(clips(1000,7000,2f));VideoPacedCaptions.prepare(p.segments,0,"one two three four",2).apply(p){};val result=VideoCaptions.parsePlaybackSrt(VideoCaptions.exportSrt(p.segments),3000);assertEquals(listOf(VideoCaption(0,1500,"one two"),VideoCaption(1500,3000,"three four")),result);assertEquals(listOf(0L,1500000L),VideoCaptions.resolve(p.segments).map{it.startUs})}
}
